// ─── File: TxnCountDemo.java ───
// Demonstrates the LEFT JOIN + COUNT(*) trap vs COUNT(child.id).
package com.bank.txncount;

import java.util.*;
import java.util.logging.*;

public class TxnCountDemo {
    private static final Logger log = Logger.getLogger(TxnCountDemo.class.getName());
    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        TxnRepository repo = new TxnRepository();
        TransactionCountService service = new TransactionCountService(repo);

        log.info("=== WRONG: LEFT JOIN + COUNT(*) ===");
        service.countStarWrong().forEach((id, c) ->
            log.warning(() -> id + " COUNT(*) = " + c + " (childless parent counts as 1!)"));

        log.info("=== CORRECT: COUNT(child.txn_id) ===");
        service.countChildKey().forEach((id, c) ->
            log.info(() -> id + " COUNT(txn_id) = " + c));

        log.info("=== COUNT(DISTINCT category) ===");
        service.countDistinctCategories().forEach((id, c) ->
            log.info(() -> id + " distinct categories = " + c));
    }
}

// ─── Would be in model/Account.java ───
class Account {
    final String accountId, holderName;
        Account(String id, String name) { this.accountId = id;
        this.holderName = name; }
}

// ─── Would be in model/Txn.java ───
class Txn {
    final String txnId, accountId, category;
    Txn(String id, String acct, String cat) {
            this.txnId = id;
            this.accountId = acct
            this.category = cat;
    }
}

