class TxnRepository {
    List<Account> accounts() {
        return List.of(new Account("SAV2001", "Rajesh Kumar"),
                       new Account("CUR3001", "Priya Sharma"));
    }
    List<Txn> txns() {
        return List.of(
            new Txn("TX1", "SAV2001", "FOOD"),
            new Txn("TX2", "SAV2001", "FOOD"),
            new Txn("TX3", "SAV2001", "FUEL"));
    }
}

// ─── Would be in service/TransactionCountService.java ───
class TransactionCountService {
    private final TxnRepository repo;
    TransactionCountService(TxnRepository repo) { this.repo = repo; }

    // Simulate the LEFT JOIN: every account gets at least one row.
    // Childless account gets one row with a NULL child (txnId == null).
    private List<String[]> leftJoin() {
        List<String[]> rows = new ArrayList<>(); // [accountId, txnIdOrNull, categoryOrNull]
        for (Account a : repo.accounts()) {
            List<Txn> matches = repo.txns().stream()
                .filter(t -> t.accountId.equals(a.accountId)).toList();
            if (matches.isEmpty()) {
                rows.add(new String[]{a.accountId, null, null}); // placeholder NULL row
            } else {
                for (Txn t : matches) rows.add(new String[]{a.accountId, t.txnId, t.category});
            }
        }
        return rows;
    }

    // WRONG: counts the placeholder NULL row too
    Map<String, Long> countStarWrong() {
        Map<String, Long> m = new LinkedHashMap<>();
        for (String[] r : leftJoin()) m.merge(r[0], 1L, Long::sum);
        return m;
    }

    // CORRECT: counts only rows where child key is non-NULL
    Map<String, Long> countChildKey() {
        Map<String, Long> m = new LinkedHashMap<>();
        for (Account a : repo.accounts()) m.putIfAbsent(a.accountId, 0L);
        for (String[] r : leftJoin())
            if (r[1] != null) m.merge(r[0], 1L, Long::sum);
        return m;
    }

    // COUNT(DISTINCT category): unique non-NULL categories per account
    Map<String, Long> countDistinctCategories() {
        Map<String, Set<String>> cats = new LinkedHashMap<>();
        for (Account a : repo.accounts()) cats.put(a.accountId, new LinkedHashSet<>());
        for (String[] r : leftJoin())
            if (r[2] != null) cats.get(r[0]).add(r[2]);
        Map<String, Long> m = new LinkedHashMap<>();
        cats.forEach((id, set) -> m.put(id, (long) set.size()));
        return m;
    }
}

